// js
const employment = ctx.subject.employment;
const terms = employment.terms;
const extension = get(employment, 'employee_extension_data', {});
const facts = get(extension, 'facts', {});
const contract = get(extension, 'term_facts', {});
const review = get(contract, 'insurance_review', null);
const current =
	get(review, 'month', '') === String(ctx.as_of).substring(0, 7) ? review : null;
const monthly = Number(get(terms, 'rate.amount', 0));
const fixed = Number(get(terms, 'allowances.FIXED_ALLOWANCE.amount', 0));
const wage = Number(get(current, 'salary_vnd', monthly + fixed));
const signed = get(employment, 'signed_contract_period', null);
const months =
	signed?.from == null || signed.to == null
		? Infinity
		: calendar_completed_months(signed.from, add_days(signed.to, 1));
const probation = get(terms, 'probation_period', null);
const onProbation = probation != null && String(ctx.run.salary_coverage.from) <= probation.to;
const foreign = ![
	'VN',
	'VNM',
	'VIETNAM',
	'VIETNAMESE',
	'Vietnam',
	'Vietnamese'
].includes(String(get(facts, 'nationality', 'VN')));
const excluded =
	get(contract, 'receiving_pension', false) === true ||
	get(facts, 'domestic_worker', false) === true ||
	get(contract, 'pass_type', '') === 'INTRA_COMPANY_TRANSFER' ||
	months < 1 ||
	(foreign && months < 12) ||
	(employment.engagement === 'PART_TIME' && wage < ctx.lookup.reference_salary) ||
	onProbation;
const insured = Math.min(
	Math.max(wage, ctx.lookup.reference_salary),
	ctx.lookup.monthly_salary_ceiling
);
const region = String(get(ctx.subject.employer.entity_extension_data, 'region', 'I'));
const minimum = get(ctx.lookup.minimum_wage_by_region, region, ctx.lookup.minimum_wage_by_region.I);
const unemployment = Math.min(
	Math.max(wage, ctx.lookup.reference_salary),
	minimum * ctx.lookup.unemployment_cap_multiple
);
const si =
	excluded ||
	get(facts, 'statutory.SI.elections.si_treaty_exempt', false) === true ||
	get(current, 'si_temporarily_suspended', false) === true;
const hi = excluded || get(facts, 'statutory.HI.elections.hi_treaty_exempt', false) === true;
const ui =
	excluded ||
	foreign ||
	get(facts, 'statutory.UI.elections.pension_qualified', false) === true;
return (
	(si ? insured * ctx.lookup.social_insurance_rate : 0) +
	(hi ? insured * ctx.lookup.health_insurance_rate : 0) +
	(ui ? unemployment * ctx.lookup.unemployment_insurance_rate : 0)
);

